const menu = document.querySelector('.menu');
const nav = document.querySelector('nav');
menu.addEventListener('click', () => { const expanded = menu.getAttribute('aria-expanded') !== 'true'; menu.setAttribute('aria-expanded', String(expanded)); nav.classList.toggle('open', expanded); });
nav.querySelectorAll('a').forEach(a => a.addEventListener('click', () => { nav.classList.remove('open'); menu.setAttribute('aria-expanded', 'false'); }));
document.querySelectorAll('[data-service]').forEach(a => a.addEventListener('click', () => { document.querySelector('#service').value = a.dataset.service; }));
document.querySelectorAll('[data-type]').forEach(a => a.addEventListener('click', () => { document.querySelector('#project-type').value = a.dataset.type; }));
document.querySelector('#brief').addEventListener('submit', event => { event.preventDefault(); const form = event.currentTarget; if (!form.reportValidity()) return; const data = new FormData(form); const subject = `Project enquiry: ${data.get('service')} — ${data.get('name')}`; const body = `Hi Mohammed,\n\nI'd like to discuss a project with Lugia International.\n\nName: ${data.get('name')}\nEmail: ${data.get('email')}\nBusiness: ${data.get('business') || 'Not specified'}\nService: ${data.get('service')}\nEngagement: ${data.get('type')}\n\nMy brief:\n${data.get('message')}\n\nThank you!`; window.location.href = `mailto:lugiainternational@gmail.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`; document.querySelector('#form-status').textContent = 'Your email draft is ready to open. If your email app didn’t open, email lugiainternational@gmail.com or use the WhatsApp link.'; });
